import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { WalletModel } from 'src/app/_models';
import { TransactionModel } from 'src/app/_models/Transaction/transactionModel';
import { WalletService } from 'src/app/_services';
import { TransactionService } from 'src/app/_services/transaction/transaction.service';

@Component({
    selector: 'app-wallet-view',
	host: { 'class': 'childRouteFlex' },
    templateUrl: './wallet-view.component.html',
    styleUrls: ['./wallet-view.component.css']
})
export class WalletViewComponent {
    constructor(
        public walletService: WalletService,
        private transactionService: TransactionService,
        private route: ActivatedRoute,
        private router: Router
    ) {

    }

    transactions: TransactionModel[] = [];
    private currentWalletId: number | null = null;

    ngOnInit(): void {
        // Access the id parameter from the route snapshot
        this.currentWalletId = parseInt(
            this.route.snapshot.paramMap.get('id') ?? '0'
        );

		if (this.walletService.wallets.length == 0) {
            this.walletService.getWalletsFromServer().subscribe(() => {
                this.walletService.selectWallet(this.currentWalletId ?? 0);
            });
        }

        this.transactionService
            .getTransactionsByWalletId(this.currentWalletId ?? 0, true)
            .subscribe((transactions: TransactionModel[]) => {
                this.transactions = transactions;
				this.transactions.sort((a, b) => (a.date > b.date ? -1 : 1));
            });
    }

    editWallet() {
		this.router.navigate(['/wallet/edit/' + this.currentWalletId]);
    }


    /* Logic for CREATE TRANSACTION */

    showButtonChoseIsIncome = false;
    firstLoad = true;

    buttonCreate: any;
    buttonCreateBefore: any;
}
<div class="component-header">
    <div>
        <i
            class="bi bi-arrow-left-circle pointer"
            [routerLink]="['/wallet']"
            style="cursor: pointer"
        ></i>
        &nbsp;&nbsp;
        <span>{{ this.walletService.selectedWallet.name }}</span>
        <i class="bi bi-pencil" 
            style="font-size: 0.9rem;   
                    margin-left: 10px; 
                    cursor: pointer;
            " (click)="editWallet()"></i>
    </div>
    <span class="header-amount">
        Balance:
        <span [ngClass]="{
            'positive-amount': this.walletService.selectedWallet.amount > 0,
            'negative-amount': this.walletService.selectedWallet.amount < 0
        }"
            >{{ this.walletService.selectedWallet.amount }}
            {{ this.walletService.selectedWallet.currencyCode }}</span
        ></span
    >
</div>

<div class="mainChild">
	<h5>Transactions</h5>

    <div class="list-container">
        <app-transaction-list
            [transactions]="transactions"
        ></app-transaction-list>
    </div>
</div>

<div
    id="buttonCreate"
    class="default-button bottom-button invert-button"
    ngClass="{{ showButtonChoseIsIncome ? 'active' : '' }}"
>
    <div
        class="button-create"
        ngClass="{{
            showButtonChoseIsIncome ? 'active' : !firstLoad ? 'off' : ''
        }}"
        (click)="createTransaction()"
    >
        <div class="button-create-text secondary">
            <span *ngIf="!showButtonChoseIsIncome">Create Transaction</span>
            <span *ngIf="showButtonChoseIsIncome"><i class="bi bi-x"></i></span>
        </div>
    </div>
    <div class="income-expense-container">
        <div
            class="sub-button"
            [routerLink]="['/transaction/create']"
            (click)="setTransactionType(true)"
        >
            <span class="income-amount">Income</span>
        </div>
        <div
            class="sub-button"
            [routerLink]="['/transaction/create']"
            (click)="setTransactionType(false)"
        >
            <span class="expense-amount">Expense</span>
        </div>
    </div>
</div>
